//! 2.7.18 regression: replay of `datasets/OIRAN_5G_PDU_SESSION_DATA_V1`
//! through `correlate_cross_interface_evidence` must emit the full
//! N2↔N4↔N3 chain (two N2↔N4 EXACT edges from IE 74/75 tunnel components
//! and two N4↔N3 EXACT edges from the PFCP F-TEID / outer-header-creation
//! vs. GTP-U destination match). The shipped `oiran_events.jsonl` is now
//! regenerated by `oiran-decode 0.6.0`, which surfaces
//! `item_<i>_tunnel_ip_ul` / `item_<i>_gtp_teid_ul` instead of the old
//! `nested_transfer_sha256`-only placeholder.

use correlation_engine::correlate_cross_interface_evidence;
use session_engine::load_path;
use std::path::PathBuf;

fn dataset_events() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("OIRAN root")
        .join("datasets/OIRAN_5G_PDU_SESSION_DATA_V1/oiran_events.jsonl")
}

#[test]
fn audit_dataset_produces_the_full_n2_n4_n3_chain() {
    let events = load_path(&dataset_events()).expect("load dataset events");
    let edges = correlate_cross_interface_evidence(&events);
    let rule_counts = edges
        .iter()
        .map(|edge| edge.rule_id.as_str())
        .fold(std::collections::BTreeMap::<&str, usize>::new(), |mut m, k| {
            *m.entry(k).or_default() += 1;
            m
        });
    assert_eq!(
        rule_counts.get("ngap-pfcp-exact-tunnel").copied(),
        Some(2),
        "two N2↔N4 EXACT tunnel edges expected (uplink 0x96a8, downlink 0x3); rules={:?}",
        rule_counts
    );
    assert_eq!(
        rule_counts
            .get("pfcp-outer-header-matches-gtpu-tunnel")
            .copied(),
        Some(2),
        "two N4↔N3 EXACT tunnel edges expected; rules={:?}",
        rule_counts
    );
    for edge in &edges {
        assert_eq!(edge.confidence, "EXACT");
    }
    // Uplink anchor: TEID 0x96a8 + UPF N3 endpoint 10.77.22.13.
    let ul_anchor = edges.iter().any(|edge| {
        edge.matching_identifiers
            .iter()
            .any(|id| id == "teid=0x96a8")
            && edge
                .matching_identifiers
                .iter()
                .any(|id| id == "endpoint_ip=10.77.22.13")
    });
    assert!(ul_anchor, "uplink TEID 0x96a8 @ 10.77.22.13 must appear");
    // Downlink anchor: TEID 0x3 + gNB N3 endpoint 10.77.22.20.
    let dl_anchor = edges.iter().any(|edge| {
        edge.matching_identifiers
            .iter()
            .any(|id| id == "teid=0x3")
            && edge
                .matching_identifiers
                .iter()
                .any(|id| id == "endpoint_ip=10.77.22.20")
    });
    assert!(dl_anchor, "downlink TEID 0x3 @ 10.77.22.20 must appear");
}
